"use client";
// @zeus-internal
import { motion, useInView } from "motion/react";
import { useEffect, useRef, useState } from "react";
import { Check, Copy } from "lucide-react";
import { ArtemisActionSwapIcon } from "../../../foundations/action-swap";
import { ARTEMIS_EASE_OUT, ARTEMIS_SPRING_PANEL, ARTEMIS_SPRING_PRESS } from "../../../lib/ease";
import { useArtemisReduceAfterHydration } from "../../../lib/use-reduce-after-hydration";
import { ArtemisActionSwapText } from "./06-profile/action-swap-text";
export default function CardsProfile() {
    const root = useRef<HTMLElement>(null);
    const inView = useInView(root, { once: true, amount: 0.2 });
    const reduce = useArtemisReduceAfterHydration();
    const [hovered, setHovered] = useState(false);
    const active = hovered && !reduce;
    const [copied, setCopied] = useState(false);
    const timer = useRef<ReturnType<typeof setTimeout> | null>(null);
    useEffect(() => () => { if (timer.current !== null)
        clearTimeout(timer.current); }, []);
    async function copyEmail() {
        try {
            await navigator.clipboard.writeText("hello@example.com");
            setCopied(true);
            if (timer.current !== null)
                clearTimeout(timer.current);
            timer.current = setTimeout(() => setCopied(false), 1600);
        }
        catch { }
    }
    return (<>
      <>
        <motion.article key={reduce ? "reduced" : "animated"} ref={root} initial={reduce ? false : { opacity: 0, y: 14 }} animate={reduce ? undefined : inView ? { opacity: 1, y: 0 } : { opacity: 0, y: 14 }} whileInView={reduce ? { opacity: 1, y: 0 } : undefined} viewport={{ once: true, amount: 0.2 }} transition={reduce ? { duration: 0 } : { duration: 0.45, ease: ARTEMIS_EASE_OUT }} onHoverStart={() => setHovered(true)} onHoverEnd={() => setHovered(false)} onFocusCapture={() => setHovered(true)} onBlurCapture={() => setHovered(false)} className="art:w-full art:max-w-sm">
          <div className="art:relative art:z-10 art:rounded-3xl art:border art:border-border art:bg-background art:p-5 art:@min-[640px]/artemis:p-6">
            <div className="art:flex art:items-center art:justify-between art:gap-4 art:text-muted-foreground art:text-xs">
              <span className="art:font-medium">
                {"Design engineer"}
              </span>
              <time className="art:tabular-nums">
                {"9:41 PM"}
              </time>
            </div>
            <div className="art:mt-6 art:grid art:grid-cols-[4.75rem_1fr] art:items-center art:gap-4">
              <motion.div animate={{ scale: active ? 1.035 : 1, rotate: active ? -1 : 0 }} transition={ARTEMIS_SPRING_PANEL} className="art:size-[4.75rem] art:overflow-hidden art:rounded-full art:border art:border-border art:bg-background">
                <img src="/assets/artemis/a5badc559b706aa529b9.svg" alt="Profile portrait" className="art:size-full art:object-cover"/>
              </motion.div>
              <div className="art:min-w-0">
                <h2 className="art:text-balance art:text-foreground art:leading-tight art:tracking-[-0.035em] art:text-4xl art:font-medium">
                  {"Alex"}
                </h2>
                <p className="art:mt-1 art:truncate art:text-sm art:text-muted-foreground art:leading-tight">
                  {"@ "}
                  {"Workspace Studio"}
                </p>
              </div>
            </div>
            <div className="art:mt-6 art:grid art:grid-cols-2 art:gap-2.5">
              <motion.a whileHover={reduce ? undefined : { scale: 1.01 }} whileTap={reduce ? undefined : { scale: 0.99 }} transition={ARTEMIS_SPRING_PRESS} className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:bg-primary art:text-primary-foreground art:hover:bg-primary/90 art:gap-2 art:px-6 art:text-base art:w-full art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:rounded-full art:h-9" href="mailto:hello@example.com" tabIndex={0}>
                {"Hire me"}
              </motion.a>
              <motion.button onClick={copyEmail} whileHover={reduce ? undefined : { scale: 1.01 }} whileTap={reduce ? undefined : { scale: 0.99 }} transition={ARTEMIS_SPRING_PRESS} type="button" className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:border art:border-border art:bg-transparent art:text-foreground art:hover:bg-primary/5 art:gap-2 art:text-base art:w-full art:px-4 art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:rounded-full art:h-9" aria-label={copied ? "Email copied" : "Copy hello@example.com"} tabIndex={0}>
                <ArtemisActionSwapIcon value={copied ? "copied" : "copy"} animation="roll" className="art:size-4">
                  {copied ? <Check className="art:size-4" aria-hidden="true"/> : <Copy className="art:size-4" aria-hidden="true"/>}
                </ArtemisActionSwapIcon>
                <ArtemisActionSwapText value={copied ? "copied" : "copy"} animation="cascade">{copied ? "Copied" : "Copy email"}</ArtemisActionSwapText>
              </motion.button>
            </div>
          </div>
          <div className="art:relative art:z-0 art:mx-4 art:-mt-6 art:flex art:min-h-16 art:items-end art:justify-center art:rounded-b-3xl art:border art:border-accent/20 art:bg-accent/10 art:px-5 art:pt-8 art:pb-3 art:text-foreground">
            <div className="art:flex art:items-center art:gap-2">
              <motion.span animate={{ scale: active ? 1.15 : 1 }} transition={ARTEMIS_SPRING_PANEL} aria-hidden="true" className="art:size-2.5 art:shrink-0 art:rounded-full art:bg-success"/>
              <span className="art:truncate art:font-medium art:text-xs">
                {"Available for work"}
              </span>
            </div>
          </div>
        </motion.article>
      </>
    </>);
}
